/* ---------- Desenho ---------- */
function layoutLabels(fig) {
  // Rótulos nas margens: separa os da esquerda e da direita e evita sobreposição (mínimo 22 px).
  var out = {}, sides = { end: [], start: [] };
  cena().hs.forEach(function (h, k) {
    var p = fig.pts[h.id]; if (!p) return;
    var o = { id: h.id, k: k, x: p[0], y: p[1], lx: p[2], ly: p[3], a: p[4] };
    if ((o.lx === 146 && o.a === "end") || (o.lx === 494 && o.a === "start")) sides[o.a].push(o); else out[h.id] = o;
  });
  ["end", "start"].forEach(function (side) {
    var arr = sides[side].sort(function (a, b) { return a.ly - b.ly; }), y = 18;
    arr.forEach(function (o) { o.ly = Math.max(o.ly, y); y = o.ly + 22; });
    var over = y - 22 - 468; if (over > 0) arr.forEach(function (o) { o.ly -= over; });
    arr.forEach(function (o) { out[o.id] = o; });
  });
  return out;
}
